+++ b/ChangeLog
@@ -1,4 +1,8 @@
-2023-09-16  Fojtik Jaroslav  <JaFojtik@yandex.com>
+2023-09-21  Fojtik Jaroslav  <JaFojtik@yandex.com>
+	* coders/bmp.c Only 16bpp and 32bpp is supported for BI_BITFIELDS
+	compression type. 8bpp is not implemented.
+
+2023-09-20  Fojtik Jaroslav  <JaFojtik@yandex.com>
 	* coders/bmp.c Remove duplicity, same information has been logged twice.
 	22:54:49 0:0.002746  0.000u 9688 bmp.c/ReadBMPImage/750/Coder:
 	File size: Claimed=8, Actual=1129
diff --git a/coders/bmp.c b/coders/bmp.c
index 72785f88a3617b0a5d8b7818be0019e5ee0c5099_Y29kZXJzL2JtcC5j..de05af6c7e6895f845579bd72ebc0a1fb6f0c320_Y29kZXJzL2JtcC5j 100644
--- a/coders/bmp.c
+++ b/coders/bmp.c
@@ -1125,22 +1125,27 @@
         case BI_BITFIELDS:
           if(bmp_info.size==40)
             {
-                 /* TODO: check for gap size >=12*/
+              if(bmp_info.ba_offset>0 && bmp_info.ba_offset<52)
+                 ThrowBMPReaderException(CorruptImageError,CorruptImage,image);	/* check for gap size >=12*/
               bmp_info.red_mask=ReadBlobLSBLong(image);
               bmp_info.green_mask=ReadBlobLSBLong(image);
               bmp_info.blue_mask=ReadBlobLSBLong(image);
             }
-          break;
+          goto CheckBitSize;
         case BI_ALPHABITFIELDS:
           if(bmp_info.size==40)
             {
-                 /* TODO: check for gap size >=12*/
+              if(bmp_info.ba_offset>0 && bmp_info.ba_offset<56)
+                 ThrowBMPReaderException(CorruptImageError,CorruptImage,image);	/* check for gap size >=16*/
               bmp_info.red_mask=ReadBlobLSBLong(image);
               bmp_info.green_mask=ReadBlobLSBLong(image);
               bmp_info.blue_mask=ReadBlobLSBLong(image);
                  /* TODO: check for gap size >=16*/
               bmp_info.alpha_mask=ReadBlobLSBLong(image);
             }
+CheckBitSize:
+          if(!(bmp_info.bits_per_pixel==16 || bmp_info.bits_per_pixel==32))
+              ThrowBMPReaderException(CorruptImageError,CorruptImage,image);
           break;

         case BI_RGB:
